type AssertFalse<Value extends false> = Value;
type AssertNever<Value extends never> = Value;
type _CommandsDoNotExtendQueries = AssertFalse<ApplicationCommands extends ApplicationQueries ? true : false>;
type _QueriesDoNotExtendCommands = AssertFalse<ApplicationQueries extends ApplicationCommands ? true : false>;
type _CapabilitiesDoNotOverlap = AssertNever<Extract<keyof ApplicationQueries, keyof ApplicationCommands>>;

type ApplicationCapabilitySource = ApplicationQueries & ApplicationCommands;

/** Bind only the compile-time key inventory supplied by a capability owner. */
function bindCapability<Source extends object, const Keys extends readonly (keyof Source)[]>(
  source: Source,
  keys: Keys,
): Pick<Source, Keys[number]> {
  const capability = Object.create(null) as Pick<Source, Keys[number]>;
  for (const key of keys) {
    const method = source[key];
    if (typeof method !== "function") throw new Error(`application_capability_method_missing:${String(key)}`);
    Object.defineProperty(capability, key, {
      configurable: false,
      enumerable: true,
      value: method.bind(source),
      writable: false,
    });
  }
  return Object.freeze(capability);
}

export function createApplicationQueries(source: ApplicationCapabilitySource): ApplicationQueries {
  return bindCapability(source, APPLICATION_QUERY_METHODS);
}

export function createApplicationCommands(source: ApplicationCapabilitySource): ApplicationCommands {
  return bindCapability(source, APPLICATION_COMMAND_METHODS);
}
